const navT=(n,dest,dir)=>n.setReactionsAsync([{trigger:{type:"ON_CLICK"},actions:[{type:"NODE",destinationId:dest.id,navigation:"NAVIGATE",transition:dir?{type:"MOVE_IN",direction:dir,easing:{type:"EASE_OUT"},duration:0.3,matchLayers:false}:{type:"DISSOLVE",easing:{type:"EASE_OUT"},duration:0.2},preserveScrollPosition:false}]}]);
await navT(W.findOne(x=>x.name=="PageIndicator"),D,"LEFT");
await navT(D.findOne(x=>x.name=="PageIndicator"),W,"RIGHT");
await navT(D.findOne(x=>x.name=="Aggressive Growth"),S3,"BOTTOM");
await navT(S3.findOne(x=>x.name=="InvestBar").children[0],S4,"LEFT");
await navT(S3.findOne(x=>x.name=="dismiss"),D);
await navT(S4.findOne(x=>x.name=="back"),S3,"RIGHT");
await navT(S4.findOne(x=>x.name=="CTA").children[0],S5,"LEFT");
await navT(S5.findOne(x=>x.name=="close"),D);
await navT(S5.findOne(x=>x.name=="CTA").children[0],W);
const btn=S4.findOne(x=>x.name=="CTA").children[0];const ic=(await g("2:106")).createInstance();btn.insertChild(0,ic);ic.findAll(x=>x.type=="VECTOR").forEach(v=>{if(v.strokes.length)v.strokes=[{type:"SOLID",color:{r:1,g:1,b:1}}];if(v.fills.length)v.fills=[{type:"SOLID",color:{r:1,g:1,b:1}}]});btn.itemSpacing=8;
figma.currentPage.flowStartingPoints=[{nodeId:W.id,name:"Wallet"}];
return "ok"

const g=async id=>figma.getNodeByIdAsync(id);
const S4=await g("11:956");const cta=S4.findOne(x=>x.name=="CTA");
const ic=(await g("2:106")).createInstance();cta.appendChild(ic);ic.layoutPositioning="ABSOLUTE";ic.x=100;ic.y=(cta.height-24)/2;
ic.findAll(x=>x.type=="VECTOR").forEach(v=>{if(v.strokes.length)v.strokes=[{type:"SOLID",color:{r:1,g:1,b:1}}];if(v.fills.length)v.fills=[{type:"SOLID",color:{r:1,g:1,b:1}}]});
figma.currentPage.flowStartingPoints=[{nodeId:"10:14",name:"Wallet"}];
const r=[];for(const id of ["10:14","10:113","11:451","11:956","11:1071"]){const f=await g(id);f.findAll(n=>n.reactions&&n.reactions.length).forEach(n=>r.push(f.name+":"+n.name+"→"+n.reactions[0].actions[0].destinationId))}
return r;

